import { getVercelOidcToken } from '@vercel/oidc';
import { eventRequest, } from '../internal/event-request.js';
import { resolveBaseUrl } from '../internal/base-url.js';
import { createConnectErrorFromResponse, } from '../token.js';
export function discoverEvents(connector, params, options) {
    return request(connector, 'events/discover', params, options);
}
/** Optional account-scoped catalog discovery; does not poll event occurrences. */
export function listEventTypes(connector, params, options) {
    const url = new URL('/v1/connect/mcp-events/event-types', resolveBaseUrl(options));
    url.searchParams.set('connector', connector);
    url.searchParams.set('tokenRequest', JSON.stringify(params.tokenParams));
    if (params.cursor !== undefined)
        url.searchParams.set('cursor', params.cursor);
    if (params.mcpUrl !== undefined)
        url.searchParams.set('sourceUrl', params.mcpUrl);
    return send(url, { method: 'GET' }, options);
}
export async function subscribe(connector, params, options) {
    if (params.expiresAt !== undefined) {
        throw new TypeError('Use ttlMs instead of expiresAt when creating a subscription.');
    }
    const { ttlMs } = params;
    if (ttlMs !== null &&
        (!Number.isInteger(ttlMs) || ttlMs < 120_000 || ttlMs > 31_536_000_000)) {
        throw new TypeError('ttlMs must be an integer from 120000 to 31536000000, or null to watch until stopped.');
    }
    return request(connector, 'subscriptions', params, options);
}
export function listSubscriptions(connector, params, options) {
    return request(connector, 'subscriptions/actions/list', params, options);
}
export function getSubscription(connector, params, options) {
    return request(connector, 'subscriptions/actions/get', params, options);
}
export function unsubscribe(connector, params, options) {
    return request(connector, 'subscriptions/actions/unsubscribe', params, options);
}
/** Stops only this connector/subject/project/environment scope. */
export function unsubscribeAll(connector, params, options) {
    return request(connector, 'subscriptions/actions/unsubscribe-all', params, options);
}
async function request(connector, operation, params, options) {
    // Serialize before awaiting auth so caller mutation cannot change the subject.
    const { mcpUrl, ...fields } = params;
    const body = JSON.stringify({
        ...fields,
        source: { type: 'mcp', url: mcpUrl },
    });
    const url = new URL(`/v1/connect/connectors/${encodeURIComponent(connector)}/${operation}`, resolveBaseUrl(options));
    return send(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body }, options);
}
function send(url, init, options) {
    const { vercelToken } = options ?? {};
    return eventRequest(options, async (signal) => {
        signal?.throwIfAborted();
        const token = vercelToken ?? (await getVercelOidcToken());
        signal?.throwIfAborted();
        const response = await fetch(url.toString(), {
            ...init,
            redirect: 'error',
            headers: {
                Accept: 'application/json',
                ...init.headers,
                Authorization: `Bearer ${token}`,
            },
            ...(signal === undefined ? {} : { signal }),
        });
        if (!response.ok)
            throw await createConnectErrorFromResponse(response, 'Failed to manage event subscriptions');
        return (await response.json());
    });
}
